"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[801],{7801:(e,t,a)=>{a.d(t,{en:()=>s});let s={meta:{authorName:"German Chernyshev",description:"Head of Engineering / Architect. Architecture \xb7 Team Leadership \xb7 Full-cycle Engineering. AI-first processes, harness for AI-assisted code. Strategy, architecture, team, quality. Design system with 70–100+ components, 20+ specialists, 30–70% faster delivery, onboarding month → week. TypeScript, Vue, React, Node.js, PHP, PostgreSQL, Docker.",skipToContent:"Skip to content"},common:{jobTitle:"Head of Engineering / Architect",focus:"Architecture \xb7 Team Leadership \xb7 Full-cycle Engineering",focusAria:"Focus",write:"Discuss a role",email:"Email",github:"GitHub"},nav:{aria:"Primary navigation",metrics:"Metrics",product:"Product",cases:"Cases",mentorship:"Mentorship",stack:"Stack",home:"Back to top",homeAlt:"Go to hero"},dragon:{openTip:"I'm here",hideTip:"Hiding",tipDialog:"Web Dragon whisper",collapse:"Collapse",tips:{hero:"Hi! I'm Web Dragon, German's assistant. I'll guide you through the page and show what matters. Ready?",metrics:"Here are the numbers. 70–100+ components, 20+ specialists, 30–70% faster. I'm no accountant, but I count well. Dragon things.",whatRemains:"I go on vacation — and it still runs. Magic? No. Process.",cases:"Three projects. Each about a real pain we solved. Ugh... those data messes still itch. But we shipped it.",article:"We cut the OpenAPI busywork. Devs stopped copy-pasting. I helped tally the time saved. Dragons are not the villain — duplication is.",mentorship:"Interview fear crushing your wings? We can prep you. Not my first century at this."}},hero:{headline:"Started in code. Now I own delivery end to end.",support:"The team ships features predictably. Business gets results it can count on.",discuss:"Discuss a role",mentorCta:"Need a mentor? Ping me."},metrics:{title:"Metrics",lead:"What I treat as important — and know how to measure.",items:{aiFirst:{value:"30–40%",label:"full cycle with AI",context:"Sped up the whole delivery cycle with AI-first: Claude + Jira, a harness with strict review and tests, agent access controls. Trained the team, ran workshops on agentic development. Typical tasks and project kickoffs got faster; releases stayed as stable — AI-written code faces the same checks as human code."},components:{value:"70–100+",label:"components",context:"Built a design system from scratch. Storybook, versions, changelog. A new developer joins and instantly sees where things live. Clear within an hour. Onboarding gets cheaper. Fewer mistakes."},specialists:{value:"20+",label:"specialists",context:"Hiring, onboarding, growth. I shape a team that delivers without endless approvals and overnight crunch before a release."},faster:{value:"30–70%",label:"faster feature shipping",context:"No AI here — architecture and the design system. A task that used to eat a week now lands in a day. New features plug in surgically. No rewriting half the product. Same team, different speed."},bugs:{value:"−45%",label:"critical bugs",context:"Bugs don't reach prod. Release pipeline and review that actually work — not checkbox theater. Rules exist so it runs, not because “we must.” On release day you press deploy."},onboarding:{value:"month → week",label:"onboarding",context:"A newcomer ships to prod in week two. Nobody whispers where constants live. The team stops burning time on explanations. Business stops paying for three weeks of idle."}}},whatRemains:{title:"What remains after me",lead:"A system that keeps living without my hands on it.",items:{aiFirst:{title:"AI-first processes",detail:"A harness for AI-assisted code, review, and tests. The team knows where an agent speeds you up — and where it creates busywork."},designSystem:{title:"Design system",detail:"Storybook, versions, changelog. New screens assemble from ready blocks."},releases:{title:"Releases without fires",detail:"Pipeline and review that catch bugs before production."},onboarding:{title:"Onboarding in a week",detail:"Order in code and docs. A newcomer takes tasks without a mentor beside them."},team:{title:"A team without handholding",detail:"Processes, agreements, and people who hold the product when I’m not in chat."}}},playunmute:{label:"Product",tryDemo:"Try it",comingSoon:"Coming soon",proof1:"I’ve run dozens of interviews. Candidates prep for the wrong thing: they grind algorithms and fall apart on simple questions. The trainer shows exactly where.",previewAlt:"Playunmute — Zoom interview simulation",features:{zoom:"Zoom interview simulation",pace:"Pace and reaction scoring",verdict:"Six-stage verdict"}},projects:{title:"Cases",kicker:"Three projects. Three outcomes.",ndaAria:"NDA projects",ndaTitle:"NDA projects",ndaText:"Links and details — in a private chat.",ndaLink:"Message on Telegram",cases:{"multi-product-platform":{title:"Multi-product event platform",summary:"Migration with no production downtime and no data loss.",description:"Legacy nobody dared to touch: ticket sales, events, personal cabinet, admin, several products. Migration to a modern stack. No production downtime. No data loss. Extra pain — data chaos: we had to structure, recover, and keep it healthy so events for thousands of players ran without outages, transactions were not lost, and registrations no longer needed managers intervening by hand like before."},"retail-platform":{title:"Retail platform",summary:"New design system. Conversion up, fewer drop-offs at checkout.",description:"B2B retail. Site, admin, personal cabinet for business clients. Thousands of users, a large product catalog. We automated processes that used to need manager intervention. Built a new design system — conversion rose, clients stopped dropping off at checkout."},"mini-apps":{title:"Telegram & VK Mini Apps, AI integrations",summary:"Deadlines others refused. Stable releases.",description:"Mini Apps and bots for Telegram and VK. Major brands, audiences from 100k users. Peak hours — tens of thousands of requests per second. Hard deadlines with no slip room: risk control, precise estimation, AI features inside the apps. We hit timelines others refused. Stable releases, bugs caught before users see them. Brands happy, team calm."}}},socialProof:{title:"GitHub article",excerpt:"15% of team time went to busywork. Ctrl+C Ctrl+V from the spec into code. I removed that. OpenAPI, codegen, predictable updates. Developers write features; the busywork stayed in the past.",readOnGithub:"Read on GitHub"},mentorship:{title:"Mentorship",lead:"Frontend and breaking into IT from scratch: I help you land a strong offer.",channelCta:"Telegram channel",cta:"Need a mentor? Ping me.",formats:{interviews:{accent:"Interviews",label:"Prep for real interview questions — intern to senior",context:"I know where people fall at every grade. Answer patterns and weak spots fixed before the HR call."},review:{accent:"Code review",label:"From fear of comments to confident decisions",context:"We review your code and your arguments: how to defend decisions and not fold under review."},playunmute:{accent:"Playunmute",label:"Trainer built for the offer",context:"Interview simulation: pace, reaction, stage verdicts — practice before the real interview."}}},skills:{title:"Stack",lead:"I pick tech for the task, the team, and the load. JavaScript, TypeScript, Vue, React, Node.js, PHP, PostgreSQL, Docker, CI/CD, WebSocket, Centrifugo. I’ve built design systems, pulled projects out of legacy, set up infrastructure and process. Language doesn’t matter — it has to work, scale, and not break.",groups:{leadership:"Leadership & team",architecture:"Architecture & systems",frontend:"Frontend",backend:"Backend & data",process:"Infrastructure & process"},tags:{leadership:"Cross-functional team leadership \xb7 Full development cycle \xb7 Hiring \xb7 Onboarding \xb7 1-on-1s \xb7 Mentorship \xb7 Engineer development \xb7 Performance review \xb7 Cross-team coordination \xb7 Clients & stakeholders",architecture:"Technical strategy \xb7 Software architecture \xb7 System design \xb7 Tech debt management \xb7 Microservices \xb7 Microfrontends \xb7 FSD \xb7 Performance Optimization \xb7 OpenAPI \xb7 Code review \xb7 Release management",frontend:"JavaScript \xb7 TypeScript \xb7 Vue.js \xb7 Nuxt.js \xb7 React \xb7 Pinia \xb7 Vuex \xb7 Redux Toolkit \xb7 Vite \xb7 Webpack \xb7 SSR \xb7 Storybook \xb7 Design Systems",backend:"Node.js \xb7 PHP \xb7 PostgreSQL \xb7 REST API \xb7 GraphQL \xb7 WebSocket \xb7 Centrifugo",process:"Docker \xb7 CI/CD \xb7 AI-first \xb7 Agent harness \xb7 Claude \xb7 Cursor \xb7 Codex \xb7 Agile \xb7 Scrum \xb7 Kanban"}},footer:{text:"Strategy, architecture, team, quality. And no dragon hunters, of course.",cta:"Telegram",contactsAria:"Contacts"},error:{title:"Something went wrong.",hint:"Reload the page or try again later."}}}}]);